  public void Initialize(BrineGameController controller){game=controller;plate=Resources.Load<Texture2D>("ui/ticket-board");sword=Resources.Load<Texture2D>("samurai-katana");impact=Font.CreateDynamicFontFromOSFont(new[]{"Impact","Arial"},24);foreach(var w in game.Model.Settings.weapons)guns[w.id]=Resources.Load<Texture2D>("weapons/"+w.art);}
  Color C(string value){ColorUtility.TryParseHtmlString(value,out var c);return c;}
  void Fill(float x,float y,float w,float h,string color){GUI.color=C(color);GUI.DrawTexture(new Rect(x,y,w,h),Texture2D.whiteTexture);GUI.color=Color.white;}
  void Text(string value,float x,float y,float w,float h,int size=16,string color=Dark,TextAnchor align=TextAnchor.UpperLeft){var style=new GUIStyle{font=impact,fontSize=size,alignment=align,wordWrap=false};style.normal.textColor=C(color);GUI.Label(new Rect(x,y,w,h),value,style);}
  bool Hot(float x,float y,float w,float h,string label){return GUI.Button(new Rect(x,y,w,h),new GUIContent("",label),GUIStyle.none);}
