   GUI.enabled=!m.UltimateActive&&m.Best>0&&m.State!=EncounterState.Defeat;if(Hot(9,365,215,62,"Gather salvage / push forward"))Act(()=>m.ToggleFarm());GUI.enabled=volley;if(Hot(232,365,209,62,"Fire volley"))Act(()=>m.Volley());GUI.enabled=true;
   Fill(13,440,149,105,Cream);Fill(162,440,54,42,Cream);bool blade=m.UltimateActive&&m.SelectedForm=="samurai";Text(blade?"BREAKWATER":m.Equipped.name.ToUpper(),16,441,192,27,22);Text(blade?"HEAVY SWORD":"EQUIPPED GUN",16,466,141,16,10,Teal);GUI.DrawTexture(new Rect(15,481,140,59),blade?sword:guns[m.Weapon],ScaleMode.ScaleToFit);GUI.enabled=tab=="road";if(Hot(162,477,46,65,"Swap weapon"))tab="gear";GUI.enabled=true;
   Fill(229,439,208,17,Cream);Text("FORM",238,439,100,17,13);GUI.enabled=!m.UltimateActive&&tab=="road";if(Button("STEP SHELL",231,458,102,28,m.SelectedForm=="step-shell"))Act(()=>m.ChooseForm("step-shell"));if(Button("SAMURAI",335,458,101,28,m.SelectedForm=="samurai"))Act(()=>m.ChooseForm("samurai"));GUI.enabled=true;
