   GUI.enabled=tab=="road"&&!m.Paused&&!m.UltimateActive&&m.State==EncounterState.Fight&&m.UltimateCharge>=100;if(Hot(231,490,207,54,"Enter selected melee form"))Act(()=>m.Ultimate());GUI.enabled=true;
   DrawUpgrades();Fill(278,664,118,35,Cream);Text(m.Gold.ToString("N0"),279,662,111,37,29,Dark,TextAnchor.MiddleRight);
